const api = await Bun.file(new URL("../packages/protocol/openapi.json", import.meta.url)).json()
const contract = {
  ...api,
  info: { ...api.info, title: "Kito Account and Model Probe API" },
  "x-backfill": "partial",
  paths: Object.fromEntries(
    Object.entries(api.paths).filter(
      ([path]) => path.startsWith("/ktai/") || path === "/api/provider/{providerID}/models/probe",
    ),
  ),
}
if (Object.keys(contract.paths).length === 0) throw new Error("Kito HTTP routes are missing from the protocol contract")
const content =
  "# Kito HTTP+JSON contract. Generated by bun run sync:kito-contract.\n" +
  "# Covers /ktai/* and provider.models.probe; upstream routes are maintained in packages/protocol.\n" +
  Bun.YAML.stringify(contract, null, 2)
    .split("\n")
    .map((line) => line.trimEnd())
    .join("\n") +
  "\n"
const file = new URL("../docs/api/openapi.yaml", import.meta.url)
if (process.argv.includes("--check")) {
  if ((await Bun.file(file).text()) !== content) {
    console.error("Kito API contract is stale. Run bun run sync:kito-contract.")
    process.exitCode = 1
  }
} else {
  await Bun.write(file, content)
}
